({ancestors:pa().int().min(1).max(8),descendants:pa().int().min(0).max(6),maxPerGeneration:pa().int().min(1).max(7).default(4)})});ct({jitless:!0});const Xc={telling:["随内容自动","事情始末","现场展开","贴近内心","逐步揭示","多方讲述","回忆讲述","传闻拼合"],pace:["随内容自动","舒缓描写","循序推进","紧凑展开","起伏鲜明","先缓后紧"],mood:["随内容自动","轻松有趣","温暖亲近","甜蜜暧昧","紧张不安","冷静克制","悲伤惋惜","热烈昂扬","复杂交织"]},_c=Ra({periods:Aa(Oa(["stable","transition","turbulent"])).min(1).max(5),telling:Oa(Xc.telling),pace:Oa(Xc.pace),mood:Oa(Xc.mood)});function $c(e){return{periods:e?.length?[...e]:["stable","transition","turbulent","stable","transition"],telling:"随内容自动",pace:"随内容自动",mood:"随内容自动"}}const eu={stable:"稳定期：所选场景中的日常秩序、资源预期或关系规则仍能维持，人们有相对可靠的生活节律。稳定不是人人幸福，更不是没有矛盾；争执、游戏、亲密关系、局部风险都可发生，不必为了高潮摧毁秩序。",transition:"过渡期：旧办法与新条件并存，身份、关系、习俗或制度正在调整，人物尝试新的应对而结果尚未定型。过渡可小到家庭和手艺的变化，不必是大战前夕，也不要求最后转为动荡。",turbulent:"动荡期：该场景中的安全、关系、资源或权威预期不可靠，选择需要面对变化、风险或摇摆。动荡不等于战争、所有人残忍或必然惨剧；可以是小群体失序，也允许善意、希望与局部安定。"},tu={事情始末:"用清楚而有温度的因果讲完整一件事。先让读者知道人物的具体处境和所求，再展示行动怎样触动别人、改变条件，最后落在可见的暂时结果上。叙述者可适度概括时日和背景，但关键转折通过场景、对话或物件落实；过渡句交代为何转变，不把缘起、经过、高潮、结果写成事项清单。特色是读后能说清“为什么会这样”，不是面面俱到的编年史；仍留下玩家可以改变进程的行动空间。",现场展开:"把读者放到事情正在发生的现场。优先从一个动作、声音、目光或有实际用途的物件进入，让人物通过做事与对话显出身份、关系和需求；环境细节参与行动，而非连续铺陈风景。重要场面尽量连贯呈现，不频繁跳出现场解释后世评价；必要背景随人物发现自然补入。特色是可看见、可听见、可介入，不是摄像头式流水账；只呈现可信感官与当时认知，不预写玩家的反应或行动。",贴近内心:"从关键人物的有限认知感受这段历史。围绕其当时想得到什么、误解什么、犹豫什么组织观察，以停顿、回避、口是心非或一个微小决定让内心显形，适度使用贴近人物口吻的自由间接叙述。外部事件仍清楚发生，心理不是脱离行动的长篇分析；若转换人物视角，应有清晰场景接续。特色是同一件事对这个人为何重要。不把未来经历、后世答案灌入当时意识，不替玩家决定情绪或动机。",逐步揭示:"让理解随着事件行动逐层加深。先给真实而不完整的现场线索，再让新的见闻、对话或行动补足来由，使早先不起眼的细节获得新的意义；每次揭示应改变人物的理解或下一步选择，而不是只拖延答案。可用误解、隐去的心意、物件用途等小谜团，不必制造阴谋或反派。特色是“原来如此”的回看感，不是故意含糊；明确史料、年龄、死亡与玩家已知结局保持准确，不把已知事实伪装成可任意翻转的谜底。",多方讲述:"让同一事件在不同人的眼中产生不同分量。挑选实际相关的少量视角，各自承担新的信息、需求或误解：当事人所求、旁观者所见、承接者所担忧可以不同。通过场景换位或转述自然接续，用动作与措辞区分人物，不让所有人复述同一过程或拥有同等知识。小事也有多方立场，不强行扩大到各国机构。特色是这些局部认识拼出更立体的事情；矛盾的是认知，不借视角差异推翻锁定事实，玩家仍可进入原事件四节点。",回忆讲述:"用今昔距离为实际往事增加回味。选择有可信身份与回忆渠道的讲述者，可从旧物、气味、地点或一句话引入往事，让如今的理解与当年的误解形成反差；回忆中的关键场景仍具体展开，叙述者只知道其经历或后来获知的部分。允许停顿、偏重与感情余韵，不需要安排一位新人物专门念史稿。特色是时间改变了事情的意味，而不是事件被改写；四个可进入节点仍属于真实事件时序，不落在后来回忆的时刻，不以记忆不可靠否定既定事实。",传闻拼合:"从有限见闻中拼出可探索的真实事件。让转述、留下的物件、现场痕迹或记录各提供不同的一块信息，交代谁为何能知道，何处只是猜测；不同说法可以体现立场和传播偏差，但读者最终仍能理解发生了什么及可介入的时刻。语言可带市井口吻或地方记忆的质感，不必把每个来源写成档案编号。特色是人与传播留下的纹理，不是全知叙述换上“据说”；明确人物身份、年龄与史料事件不因传闻随意改动，也不强造真假难辨的阴谋。",舒缓描写:"给有意义的瞬间以停留空间。准备、等待、相处与观察可以细写，用触觉、声音、动作间隙和环境变化积累人物关系，使读者感到时间经过；长短句交替，场景之间自然呼吸，略去对人物和事件没有作用的景物堆砌。四阶段仍向前发展，舒缓不等于没有事件。特色是细节在转折时产生分量，而非篇幅冗长；紧急动作按真实速度发生，战争中可以舒缓地写冲锋前的挂念，但不能让冲锋途中无理由停下来闲谈。",循序推进:"沿行动的实际次序稳健展开。一个决定引出回应，回应带来新的条件，再由人物处理后果；在时间跳跃处给出必要过桥，使读者不靠猜测才能接上人物、物件与地点。常态段落简洁，关键选择适度展开，各阶段篇幅依据事件分量分配。特色是步步可追踪、读起来顺畅，不是平均节拍的四段模板。允许必要回看但不打乱事件时序，不用“随后发生巨变”跨过关键因果，也不把已知年龄和时间锚在过渡中省略。",紧凑展开:"尽早进入人物真正需要处理的事情。开头快速建立必要场景和需求，行动、对话与发现接连改变条件；压缩重复背景、无作用的走路过程与同义心理描写，转折处仍保留决定、执行和后果，让节奏紧而因果不断。句子可以利落，但不要求全文短句或每段都发生危机。特色是每个场面都推进理解或选择；不可把人物动机、必要时间跨度、年龄事实或四节点介入空间压成一句，不因紧凑而添加追逐、打斗或险境。",起伏鲜明:"让事件出现可感的期待与落差。围绕人物的真实小目标组织尝试、阻碍、转机和回应，张弛可来自关系变化、误解解除、发现新用途或得失转换；在重点瞬间略作停留，其他过渡简洁，使波峰和低谷有比较。玩积木也可由搭成、倒塌、争执和重新合作构成起伏。特色是局面与心情真的发生变化，不是不断叠加刺激；不为起伏制造死亡、大战、万能反派或无由反转，四阶段不必每段等量戏剧化。",先缓后紧:"让压力从已有条件中逐渐聚集。开篇用有意义的日常与准备建立人物所珍惜的东西，埋下已经存在的期限、误会、资源变化或未处理的问题；中段让这些条件相互牵动，后段缩短行动间隔、增加回应密度，走到不得不作出选择的瞬间。前文细节在后文有实际用途。特色是读者感到“事情已不能照旧”，不一定是危险临近；紧迫程度随题材调整，小事可只是错过一班车或说出一句话，不强行升级为灾难，也不逆转史料。",轻松有趣:"从人物认真生活时的细小错位产生趣味。利用性格差异、笨拙尝试、误会、巧合或物件的不合时宜，让人物各有其合理目的，读者因理解处境而会心一笑；对话可灵动，叙述保留善意，笑点有铺垫和回应而非网络段子堆砌。特色是小事也有鲜活的可爱与机锋。严肃题材可只在此前日常或人物相处中局部使用，不嘲弄真实苦难与受害者，不改变死亡、伤害或行为后果来把历史写成无代价闹剧。",温暖亲近:"让温度来自具体而不夸张的照顾。通过递来一件工具、记住一个习惯、耐心解释、共同分担或笨拙的善意表现人与人的联系，语言贴近日常，允许不说出口的感激和理解；困难仍真实存在，温暖不必获得宏大奖赏。特色是人与生活之间的信任，而非所有角色突然宽容善良。适用于亲情、友谊、师徒和同伴等有依据的关系；不粉饰已知伤害、不强制和解、不改写史料结局，也不让陌生人无缘无故像家人一样亲近。",甜蜜暧昧:"让亲近藏在成年人之间尚未明说的心意里。适合时用目光停留、试探话语、互相记得的小事、克制触碰、承诺与挂念表现距离的缩短，场面有分寸，语言轻柔而不靠生硬情话或身体描写堆砌。特色是彼此知道又未完全说破的张力，不是给题材强配爱情。关系无依据时弱化或退让；冲锋题材可局部写已有爱人的信与牵挂，不能为每位士兵新配恋人。不把幼年人物成人化，不让甜蜜掩盖战争、伤害或人物真实选择。",紧张不安:"让悬而未决的风险在细节里积累。围绕当事人确实不知道、担心失去或来不及完成的事情组织观察，用迟来的回应、异常安静、逐渐逼近的期限、行动受阻等让读者感到压力；句段可收紧，关键判断前适度停顿，不用反复声明“很可怕”。特色是有限信息下的等待与选择，而非所有人不停惊叫。风险须有来源和尺度，普通小事也可以使人忐忑；不凭空加入邪恶势力、追杀或灾难，不让当时人物预知后世结果。",冷静克制:"让事实和动作自己承担重量。以具体、清晰的叙述呈现人物怎么做、付出什么、留下什么，减少情绪判词与夸张修辞，用未说完的话、收回的动作、留下的空位或重复出现的旧物表达余意。对话简洁但符合人物，不抹去必要动机和感受。特色是读者从有限细节中体会分量，不是全篇无情绪的公文。适用于任何规模的事件，重大伤害可克制呈现而非感官猎奇；不以“秩序”“结算”等抽象词替代具体人生，也不把玩家反应写定。",悲伤惋惜:"写出想留下却没能留下的东西。围绕错过、未说出口的话、童年流逝、误解、失落或未完成的小事，先让读者看见人物真正在乎什么，再由一个物件、空位、习惯或迟到的理解带出余韵；悲意可与温暖、微笑并存，措辞节制，不连续使用痛苦形容词。特色是回望时多了一层无法追回的意味。幼年玩积木可惜的是误会或童年片刻，不必有人受伤；不强制死亡和灾难，不改写已知结局制造悲剧，也不利用创伤反复煽情。",热烈昂扬:"让投入与勇气在行动中显现。通过共同尝试、接力回应、坚持一项手艺、守护伙伴或不肯放弃的小目标积累情绪，使用有力量但具体的动词与逐步展开的场面，让昂扬从人物真正承担的代价里生长。可以是大事，也可以是第一次完成小作品的雀跃。特色是生命力与愿意向前的姿态，不是全知作者替所有人发表宣言；允许恐惧、牺牲与不完美，不用口号代替人物、不保证胜利，也不改写既定伤亡来获得爽快收尾。",复杂交织:"让同一事件承载不同而相连的感受。围绕具体人物的取舍，展示希望中夹着犹疑、亲近中有戒备、得到时仍有遗憾等反差；让这些变化通过对话、行动与时机呈现，不在每段列出一串情绪名称。可以选一个主要底色，其余情绪在不同场面自然浮现，不要求每种感觉都齐全。特色是人物难以用一句好坏概括的生活滋味，而非故意晦涩。情绪冲突不能成为篡改身份、年龄、历史事件或无据增加悲惨经历的理由，收尾可留余味但因果仍清楚。"},nu={telling:"依据题材最值得观察的关系选择叙述视角。需要理解因果时讲清始末，重要交往可现场展开，认知有限时贴近内心或逐步揭示；不同候选可以有不同的观察重心，不机械轮换同一模板。背景说明服务事件，不用档案术语代替具体场面，四个可介入节点仍对应真实时序；史料已定的身份、年龄与事件不因视角变化而改写。",pace:"依据事件真实的压力和分量安排张弛。准备与相处可停留，关键决定和转折细写，无作用的过渡简洁带过；紧急行动按其真实速度发生，长时间演变用清楚过桥接续。不同阶段不必等长，自动不是平均分成四段，也不是默认越写越惨烈；不为提速添加危机，不为舒缓硬塞风景，保留必要动机和玩家可介入空间。",mood:"从人物实际得失与关系自然生长情绪。轻松、亲近、紧张、惋惜或昂扬取决于具体行动的意味，可以混合与局部反差，不先规定赢家和结局。普通小事不自动升级为阴谋或灾难，严肃题材不被强行写成笑话；不因情绪偏好增添亲缘、恋人、伤害与死亡，不把幼年人物成人化，允许惊喜但既定史料事实始终保留。"},ru={telling:{随内容自动:"先找本事件最值得读者跟随的理解路径，再沿这条路径组织场面。行动后果重要时采用清晰因果，关系细微时进入现场，秘密只被局部知道时随发现展开；同一篇可在自然接缝处改变距离，但主要视角应可辨。让开头提出一个实际值得关心的问题，中段通过人的动作回答它，末尾留下这个题材特有的余味，而不是为每篇套上同一位全知史官的口吻。",事情始末:"突出一件事为什么开始、怎样发展、又留下什么结果的因果接续。开篇交代推动人物行动的具体缘由；每次局面改变，都让读者看见决定、回应和新条件之间的联系。背景可概述，决定性的交涉或选择则展开成场面；段落衔接用实际理由而不只用“随后”。收尾回到最初所求，看它得到、落空还是被重新理解，形成完整事件的回味。",现场展开:"以现场一个可见动作开门，让感官、空间和对话接连推动事情。描写谁站在哪里、伸手碰到了什么、谁听见了一句怎样的话；物件在人物使用中显出质地，身份在应答和分工中显出。需要交代背景时，可由人物遇到的阻碍或熟悉的习惯带出。重要瞬间让动作实际完成再转场，使读者像身在其中而非听人事后汇报；停留的细节都与眼前变化有关系。",贴近内心:"把同一场面的细节染上焦点人物当时的注意、误解和欲望。别人只是一句寻常话，对他却可能是试探、承诺或羞耻；先呈现他注意到的东西，再以停顿、躲闪或小决定显出解释。心念可随行动短暂游移，随后回到身体和场面；让读者理解他为何这样做，同时看出他尚不知道的部分。内心变化有过程，区别于旁观者直接宣告“他很难过”。",逐步揭示:"让每次新发现改变读者对同一件事的理解，而不只是增加资料。先给可成立的局部印象，再让话语、行为或旧物补上缺口；前面不起眼的细节在后来获得新的含义。揭示可修正动机、关系或误会，节奏围绕“现在比刚才明白了什么”展开。末段回应此前的问题，让读者能回看线索的来由；知道真相的人有知情渠道，未知之处仍留给玩家探索。",多方讲述:"让不同立场各贡献一块不可由上一视角替代的信息。围绕同一行动或物件接续少量视角：有人重视做法，有人看见代价，有人只记得关系变化。切换时用姓名、地点或正在做的事情帮助读者定位；后来视角可以使先前行为获得另一层意义，但不反复复述整场经过。共同事实把各段扣在一起，分歧来自生活位置和认知，合起来比任何一方独讲更完整。",回忆讲述:"以如今与当年的理解差为往事增加回味。当前的旧物、地点或声音触发回看，进入往事后把当年的关键场景真正演出来；回忆者可在少数停顿处指出自己当时不懂、后来才明白的事。措辞带经历沉淀后的亲近、迟疑或轻微自嘲，而不只是把普通叙述改成过去式。最后回到触发回忆的细节，读者感到年月改变了意义，实际可介入节点仍落在往事之中。",传闻拼合:"以不同知情渠道的碎片相互补证，显出故事在流传中的纹理。一次亲眼见闻、一句转述、一个留下的痕迹各回答不同问题；说法的偏差来自谁想保全面子、谁只看见半场、谁多年后记错了细节。叙述自然交代可信程度，再沿共同可确认的部分接成真实事件。口气可随渠道略变，却始终让读者找到发生地点、关键行动和可介入时刻，不把含混本身当成深奥。"},pace:{随内容自动:"把叙事时间留给真正改变人物理解或选择的瞬间。可用一两句渡过无变化的时日，把一次交谈、动手或等待细写；紧急行动连贯前进，事后再给感受回落的空间。段落长短随场面功能改变，既有呼吸也有推进。先判断哪里值得慢看、哪里只需过桥，再安排四阶段的分量，使不同题材有自己的节拍，而不是一律平铺或一律赶向爆点。",舒缓描写:"延长有意义瞬间的体验时间，使细节慢慢获得情感分量。一个动作可写到准备、接触、回应与余响，等待中让声音、手势或光线体现细小变化；人物关系在这些间隙里逐渐被读者理解。较长句舒展观察，短句落在一个确实发生的小改变上；较大的时间跳跃用简短过桥带过。缓的是观察和体会，不是实际危急动作的速度，也不是用更多形容词拖长篇幅。",循序推进:"让读者沿每一步行动清楚接到下一步结果。先有具体需要，再有尝试，回应改变条件，人物据此调整；时间或地点变动时顺手交代承接物和原因。段落以一个局面完成或一个新条件形成来收束，下一段由它出发。平稳来自步步有来由，重要选择仍可停下来细写；小高潮可以自然长在过程里，读者不用依赖突兀的“原来一切早有安排”才能读懂。",紧凑展开:"减少空转，让每个场面都带来新的行动、信息或选择。从最接近事件核心的时刻切入，背景随用随补；对话回应紧邻它引起的动作，转场尽快落在变化后的局面。短句适合决定与反应，必要说明可用清晰长句衔接，不必全篇同一节拍。篇幅省在重复铺垫与无效过渡上，关键动机和后果保留，使读者被事情牵着走，而不是因跳步而茫然。",起伏鲜明:"以期待与实际回应的落差安排波峰和低谷。先让人物认真投入一个具体目标，随后改变进展、关系或理解，再让其作出回应；顺利处可轻快，失落或转机处稍作停留。段末可以落在一句话、一个动作或新局面上，下一段承接它形成反差。起伏的来源随题材而变，日常小事也有轻重与得失，高潮是此前积累真正发生作用的时刻，而非凭空加大灾难。",先缓后紧:"让场面密度随已有问题逐步聚拢，形成可以感到的加速。开头留出认识日常和人物所珍惜之物的空间，一处期限、误会或未完成的事先轻轻出现；随着条件交汇，选择变少、动作间隔缩短、回应更直接。句段可以从舒展转为利落，前面的物件或话语在后面派上用场。收尾允许一口缓气，紧迫是事件真实进程的收束，不必演成险情。"},mood:{随内容自动:"从这一次真实得失中辨认主要情绪，再让细节而非标签传达它。看人物在乎什么、期待什么、实际得到什么，用应答、行动和物件使温度逐渐形成；一个场面可先轻快再沉静，或在艰难中保有亲近。选取适合当事人的语气和感官重心，情绪转变有可见触发，不把所有人写成相同反应。末尾留一点属于这件事的感觉，而非统一升华为历史大道理。",轻松有趣:"从认真目的之间的小错位长出会心的笑，而不是直接宣布事情滑稽。铺垫一个可理解的习惯、误会或笨拙办法，让它在应答、动作或物件用途上得到自然回响；人物有自己的尊严，旁人也有合理立场。对话节奏可稍灵巧，措辞轻盈，笑过后事情仍真实向前。趣味可以藏在严肃人物的一点破绽里，也可以是读者比当事人先看明白的小反差。",温暖亲近:"让被注意、被理解和被照顾的感觉藏在具体的小事里。记得对方的习惯、主动多做一步、在困难中耐心等候，都能让关系变近；描写回应如何迟疑、接受或轻轻回赠，使善意有往返而非单向称颂。语言贴近生活，感官重心可落在温度、熟悉声音和共同使用的物件上。温暖不是困难消失，而是人有了一点可以依靠的联系，收尾可留在一个平凡动作。",甜蜜暧昧:"让成年人的心意在靠近与克制之间流动，重心放在尚未说破的默契。一次多停留的目光、带双重意味的问答、早已记住却假装随口的小事，都可以改变双方对距离的感受。场面有试探、有回应，也允许退开或误会；措辞柔和，读者能从差别看出在意，而非依赖直白告白。题材不适合恋爱时只沿已有成年关系的挂念局部表现，事实与人物意愿优先。",紧张不安:"让等待中的未知通过正常节律被打断而变得可感。迟迟没有的答复、与惯常不同的声音、逐渐逼近的时刻，都可使人物多看一眼或改变动作；读者知道担心的对象，却未必立刻知道结果。必要处短暂停顿，随后让真实回应释放或改变压力，词句随注意力收窄。紧张可只是害怕一件小事做不好，悬念的分量来自当事人的在乎，不来自不断提高危险等级。",冷静克制:"把感受交给少量准确动作和留白，让读者自己体会重量。叙述选择最有分量的细节，一句没有答完的话、一个收回的手势、仍摆着的旧物即可承载变化；对話保持人物本来的用词，情绪无需由作者逐段解释。句子清楚，修辞适度，段末可以停在事实余响上。克制不等于冷漠或官样文章，人物为什么行动仍可理解，只是更少替读者下判断。",悲伤惋惜:"先写出人曾经珍惜的具体事物，再让它的变化留下余韵。日常的熟悉、曾经的期待或一句未及时说出口的话，与后来空出来的位置、变了的习惯形成呼应；情绪可以晚于事件才被当事人理解。语言不急于号哭，温暖与微笑也能使遗憾更深。可惜的是失去的可能、错过的片刻或再也不相同的相处，收尾留在一个细节上，不把悲意等同于追加伤亡。",热烈昂扬:"让投入在彼此应答、共同承担和实际行动中逐渐升温。人物的尝试获得回应，犹豫被某个具体理由推动，一次小成功或坚持又鼓舞下一步；动词有力度，对话有各自声音，句段可在关键处形成接力般的节奏。昂扬仍容得下疲惫与恐惧，它来自愿意做而非必定赢。高潮落在真正完成、承担或选择的瞬间，让读者看见生命力，不用统一宣言盖过人物。",复杂交织:"让同一个选择同时带着所得与所失，使情绪由具体矛盾相互牵动。人物可以因靠近而欣喜又因暴露弱处而戒备，得偿所愿后仍惦记被放下的东西；先呈现行动，再让不同感受在回应和余响中浮现。可围绕一个主色调留出反调，句段随人物理解变化而换温度。收尾允许一句话无法概括全部滋味，但事件本身仍清楚，不靠堆砌情绪形容词显得复杂。"}};function su(e,t){const n=Xc[e].find(e=>e===t)??"随内容自动";return`${"随内容自动"===n?nu[e]:tu[n]}
